// Load jQuery
const loadScript = (src, callback) => {
    const script = document.createElement('script');
    script.src = src;
    script.onload = callback;
    document.head.appendChild(script);
};

// Load jQuery first, then Webflow script
loadScript('js/jquery-3.5.1.min.js', () => {
    console.log('jQuery loaded');
    loadScript('js/webflow.5f5556b80.js', () => {
        console.log('Webflow script loaded');
        initCustomScripts();
    });
});

function initCustomScripts() {
    // Hamburger Menu Toggle
    const hamburger = document.getElementById('hamburger');
    const menu = document.getElementById('menu');
    
    if (hamburger && menu) {
        hamburger.addEventListener('click', () => {
            hamburger.classList.toggle('active');
            menu.classList.toggle('active');
        });
    }

    // Additional custom JS if needed
    console.log('Custom scripts initialized');
}
